import sys,time,random
sys.path.insert(0,'/app/submission');import main

def mk(n,m,typ):
    # R=0 makes all states done, so use R=1 and all non-done empty delivered
    states=[{'delivered':[[]],'slots':[]} for _ in range(n)]
    edges=[]
    if typ=='chain':
      for i in range(n-1):edges.append([i,'a',i+1])
      for i in range(n-1,m):edges.append([random.randrange(n),'b',random.randrange(n)])
    elif typ=='cycle':
      for i in range(n):edges.append([i,'a',(i+1)%n])
      for i in range(n,m):edges.append([random.randrange(n),'b',random.randrange(n)])
    elif typ=='self':
      for i in range(n):edges.append([i,'a',i])
      for i in range(n,m):edges.append([random.randrange(n),'b',random.randrange(n)])
    else:
      for i in range(m):edges.append([random.randrange(n),random.choice(['a','b']),random.randrange(n)])
    # dedup may lower m
    edges=[list(x) for x in dict.fromkeys(tuple(x) for x in edges)]
    fairness=[{'action':'a','mode':'strong'}]
    return {'op':'audit','inputs':[[[0]]],'states':states,'edges':edges,'start':0,'fairness':fairness}
for typ in ['chain','cycle','self','random']:
  o=mk(12000,60000,typ);t=time.time();g=main.validate_graph(o);print(typ,'validated',time.time()-t,len(g['edges']));t=time.time();res=main.audit(g);print('audit',time.time()-t,res['terminates'],len(res['liveness']['loop']) if res['liveness'] else None)
